def __bool__(self):
    """
    Return True if the progress bar has not finished, False otherwise.
    """
    if self.disable:
        return False
    if self.total is None:
        return True
    return self.n < self.total

def __len__(self):
    if self.disable:
        return 0
    if self.iterable is not None:
        try:
            return len(self.iterable)
        except TypeError:
            pass
    return self.total if self.total is not None else float('inf')
