```python
def __bool__(self):
    """
    Return True if the progress bar has a total or iterable, False otherwise.
    """
    return hasattr(self, 'total') and self.total is not None or self.iterable is not None

def __len__(self):
    if self.disable:
        return 0
    return self.total if self.iterable is None else \
           (self.iterable.shape[0] if hasattr(self.iterable, "shape")
            else len(self.iterable) if hasattr(self.iterable, "__len__")
            else getattr(self, "total", None))
```
